//! Turns a request in natural language (typed after `#`) into a shell command,
//! like Warp's AI command search. The command is generated by Claude Code's
//! non-interactive mode (`claude -p`), so it uses the user's own Claude
//! subscription and needs no API key in Solo.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

use anyhow::{Result, anyhow};

use super::completion::{ShellFlavor, run_with_timeout};

const TIMEOUT: Duration = Duration::from_secs(90);

/// Generates a command for `request`, run from `cwd` in `shell`.
pub fn generate_command(request: &str, shell: Option<&str>, cwd: Option<&Path>) -> Result<String> {
    let claude = find_claude().ok_or_else(|| {
        anyhow!("Claude Code isn't installed (no `claude` on PATH), so commands can't be generated")
    })?;
    let mut command = Command::new(claude);
    command
        .arg("-p")
        .arg(prompt(request, shell, cwd))
        .args(["--output-format", "text"]);
    if let Some(cwd) = cwd {
        command.current_dir(cwd);
    }
    let output = run_with_timeout(command, TIMEOUT)
        .ok_or_else(|| anyhow!("Claude Code didn't answer within {}s", TIMEOUT.as_secs()))?;
    let command = clean_answer(&output);
    if command.is_empty() {
        return Err(anyhow!("Claude Code returned no command"));
    }
    Ok(command)
}

fn prompt(request: &str, shell: Option<&str>, cwd: Option<&Path>) -> String {
    let shell_name = match ShellFlavor::from_shell(shell) {
        ShellFlavor::PowerShell => "PowerShell",
        ShellFlavor::Posix => "bash",
    };
    let os = if cfg!(windows) {
        "Windows"
    } else if cfg!(target_os = "macos") {
        "macOS"
    } else {
        "Linux"
    };
    let cwd = cwd
        .map(|cwd| format!(" The working directory is {}.", cwd.display()))
        .unwrap_or_default();
    format!(
        "Write a {shell_name} command for {os} that does the following.{cwd} \
         Reply with only the command, on as few lines as possible, with no \
         explanation, no markdown and no code fences. Don't run anything.\n\n\
         Task: {request}"
    )
}

/// Strips code fences, a leading prompt sign and surrounding blank lines.
fn clean_answer(answer: &str) -> String {
    let lines: Vec<&str> = answer
        .lines()
        .filter(|line| !line.trim_start().starts_with("```"))
        .collect();
    let text = lines.join("\n");
    let text = text.trim();
    let text = text
        .strip_prefix("$ ")
        .or_else(|| text.strip_prefix("PS> "))
        .unwrap_or(text);
    text.trim_matches('`').trim().to_string()
}

/// Claude Code's executable: on `PATH`, or where its native installer puts it.
fn find_claude() -> Option<PathBuf> {
    let names: &[&str] = if cfg!(windows) {
        &["claude.exe", "claude.cmd"]
    } else {
        &["claude"]
    };
    let path = std::env::var_os("PATH").unwrap_or_default();
    std::env::split_paths(&path)
        .chain(
            std::env::var_os(if cfg!(windows) { "USERPROFILE" } else { "HOME" })
                .map(|home| PathBuf::from(home).join(".local").join("bin")),
        )
        .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
        .find(|candidate| candidate.is_file())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_clean_answer() {
        assert_eq!(
            clean_answer("```powershell\nGet-ChildItem\n```\n"),
            "Get-ChildItem"
        );
        assert_eq!(clean_answer("  `ls -la`  "), "ls -la");
        assert_eq!(clean_answer("$ du -sh *\n"), "du -sh *");
        assert_eq!(
            clean_answer("Get-ChildItem |\n  Sort-Object Length"),
            "Get-ChildItem |\n  Sort-Object Length"
        );
    }

    #[test]
    fn test_prompt_mentions_shell_and_task() {
        let prompt = prompt("list big files", Some(r"C:\x\pwsh.exe"), None);
        assert!(prompt.contains("PowerShell"));
        assert!(prompt.ends_with("Task: list big files"));
    }
}
